import { useContext } from 'react';
import { useUIContext } from '../../hooks/useUIContext';

export function ThemeSwitcher() {
    const {theme, setTheme} = useUIContext();

    return (
        <div>
            <p>Current theme: {theme}</p>
            <button onClick={() => setTheme('light')}>Light Theme</button>
            <button onClick={() => setTheme('dark')}>Dark Theme</button>
        </div>
    );
}`,language:"typescript"})})},{title:"Responsive Helpers",content:({Syntax:e})=>jsxRuntimeExports.jsx("div",{style:{},children:jsxRuntimeExports.jsx(e,{code:`// Example usage of isMobile, isTablet, and isDesktop
